CREATE TABLE public.provider_cancellation_requests (subscription_id uuid PRIMARY KEY REFERENCES public.subscriptions(id), user_id uuid NOT NULL, provider_subscription_id text NOT NULL, reason text NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','processing','confirmed','failed')), attempts integer NOT NULL DEFAULT 0, next_retry_at timestamptz DEFAULT now(), lease_until timestamptz, last_error text, confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.provider_cancellation_requests TO authenticated;
GRANT ALL ON public.provider_cancellation_requests TO service_role;
ALTER TABLE public.provider_cancellation_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_cancellations ON public.provider_cancellation_requests FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'));
CREATE INDEX provider_cancellation_due_idx ON public.provider_cancellation_requests(next_retry_at) WHERE state IN ('pending','processing');
CREATE UNIQUE INDEX payment_incidents_post_cancel_charge_unique ON public.payment_incidents(charge_id) WHERE kind='post_cancel_renewal' AND charge_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.claim_provider_cancellation(p_subscription_id uuid) RETURNS SETOF public.provider_cancellation_requests LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.provider_cancellation_requests SET state='processing',lease_until=now()+interval '2 minutes',attempts=attempts+1,updated_at=now() WHERE subscription_id=p_subscription_id AND state IN ('pending','processing') AND (lease_until IS NULL OR lease_until<now()) RETURNING * $$;
REVOKE ALL ON FUNCTION public.claim_provider_cancellation(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_provider_cancellation(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.prevent_cancelled_payment_reactivation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='active' AND OLD.status IS DISTINCT FROM 'active' AND (OLD.cancel_at_period_end OR OLD.cancelled_at IS NOT NULL OR OLD.status IN ('cancelled','refunded','refunded_duplicate') OR EXISTS(SELECT 1 FROM public.refund_requests WHERE subscription_id=OLD.id AND status IN ('processed','approved') AND NOT keep_access)) THEN RAISE EXCEPTION 'cancelled_subscription_cannot_reactivate'; END IF; RETURN NEW; END $$;
CREATE TRIGGER prevent_cancelled_payment_reactivation BEFORE UPDATE OF status ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.prevent_cancelled_payment_reactivation();